def shortest_paths(nodes, links, source):
    # Directed adjacency over up links only.
    adj = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            adj[link["from"]].append((link["to"], link["cost"]))

    cost_of = {n: None for n in nodes}
    path_of = {n: None for n in nodes}
    cost_of[source] = 0
    path_of[source] = [source]
    settled = set()

    # Dijkstra with O(V^2) selection. All link costs are >= 1, so every
    # predecessor of a lowest-cost path has a strictly smaller cost and is
    # settled before the node itself; hence only costs are compared during
    # selection, and full path sequences only during relaxation ties.
    while True:
        u = None
        ucost = None
        for n in nodes:
            c = cost_of[n]
            if c is not None and n not in settled and (ucost is None or c < ucost):
                u = n
                ucost = c
        if u is None:
            break
        settled.add(u)
        upath = path_of[u]
        for to, w in adj[u]:
            if to in settled:
                continue
            nc = ucost + w
            cc = cost_of[to]
            if cc is None or nc < cc:
                cost_of[to] = nc
                path_of[to] = upath + [to]
            elif nc == cc:
                cand = upath + [to]
                if cand < path_of[to]:
                    path_of[to] = cand
    return cost_of, path_of


def compute_routes(nodes, links, source):
    cost_of, path_of = shortest_paths(nodes, links, source)

    routes = []
    for n in sorted(nodes):
        if n == source:
            routes.append({"destination": n, "nextHop": source, "cost": 0,
                           "path": [source]})
        elif cost_of[n] is None:
            routes.append({"destination": n, "nextHop": None, "cost": None,
                           "path": []})
        else:
            p = path_of[n]
            routes.append({"destination": n, "nextHop": p[1],
                           "cost": cost_of[n], "path": p})
    return {"source": source, "routes": routes}


def compute_metric(nodes, links, source, order_names):
    # Directed adjacency over up links only.
    adj = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            adj[link["from"]].append(
                (link["to"], link["cost"], link["bandwidth"], link["latency"]))

    # Enumerate every directed simple path from the source via DFS and keep
    # the best one per destination under the ORDER metric hierarchy. Ties on
    # every metric go to the path with the smallest Unicode code point order.
    # best[n] = (comparison_key, (hop, cost, bandwidth, latency), path)
    best = {}

    def metric_key(hop_count, cost, bandwidth, latency):
        m = {"hop": hop_count, "cost": cost, "bandwidth": bandwidth,
             "latency": latency}
        # bandwidth prefers the larger value; the others the smaller.
        return tuple(-m[name] if name == "bandwidth" else m[name]
                     for name in order_names)

    def consider(path, hop_count, cost, bandwidth, latency):
        key = metric_key(hop_count, cost, bandwidth, latency)
        dest = path[-1]
        cur = best.get(dest)
        if cur is None or key < cur[0] or (key == cur[0] and path < cur[2]):
            best[dest] = (key, (hop_count, cost, bandwidth, latency),
                          list(path))

def _config_capacity_six(num, den):
    # num/den rounded half up to six decimals like _format_peak.
    scaled = (2 * num * 1000000 + den) // (2 * den)
    return "%d.%06d" % (scaled // 1000000, scaled % 1000000)


def _config_capacity_delta_six(new_num, new_den, old_num, old_den):
    # Signed six-decimal rendering of newPeak - oldPeak, rounded half up
    # from the exact rational difference (not a subtraction of rounded
    # strings); an exact zero is "0.000000". All arithmetic is integer.
    delta_num = new_num * old_den - old_num * new_den
    delta_den = new_den * old_den
    if delta_num == 0:
        return "0.000000"
    sign = "-" if delta_num < 0 else "+"
    scaled = (2 * abs(delta_num) * 1000000 + delta_den) // (2 * delta_den)
    body = "%d.%06d" % (scaled // 1000000, scaled % 1000000)
    return sign + body


def _config_capacity_side(nodes, links, flows, flow_count):
    # Route every flow on one topology: the route subcommand's lowest-
    # cost path over up links with the full-node-sequence Unicode tie
    # break, one Dijkstra per distinct source. Returns
    # (paths, costs, used, peak(Num,Den), all_reachable, any_overload).
    # used is indexed by the links array (candidate topology order);
    # peak is the exact max used/bandwidth fraction over every link; a
    # flow whose endpoint is absent from this topology or that has no up
    # path leaves a None slot and clears all_reachable (its demand then
    # contributes no load). O(K(V^2 + A) + FV + A) for K distinct
    # sources, F flows, V nodes, and A links.
    node_set = set(nodes)
    cost_of = {}
    path_of = {}
    paths = [None] * flow_count
    costs = [None] * flow_count
    reachable = True
    for i, item in enumerate(flows):
        s, d = item[1], item[2]
        if s not in node_set or d not in node_set:
            reachable = False
            continue
        if s not in cost_of:
            cost_of[s], path_of[s] = shortest_paths(nodes, links, s)
        path = path_of[s][d]
        if path is None:
            reachable = False
            continue
        paths[i] = path
        costs[i] = cost_of[s][d]
    used = [0] * len(links)
    index_of = {}
    for index, link in enumerate(links):
        index_of[(link["from"], link["to"])] = index
    for i, item in enumerate(flows):
        if paths[i] is None:
            continue
        path = paths[i]
        demand = item[3]
        for a, c in zip(path, path[1:]):
            used[index_of[(a, c)]] += demand
    peak_num, peak_den = 0, 1
    over = False
    for index, link in enumerate(links):
        u, bw = used[index], link["bandwidth"]
        if u > bw:
            over = True
        if u * peak_den > peak_num * bw:
            peak_num, peak_den = u, bw
    return paths, costs, used, (peak_num, peak_den), reachable, over


